performance_stage_sources.autobuyer_benchmark.gd:
extends SceneTree

const Runner = preload("res://tests/experimental/autobuyer_offline.gd")
const Previous = preload("res://tests/experimental/horizon_runner.gd")
const Fixtures = preload("res://tests/experimental/autobuyer_fixtures.gd")
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")
const Observer = preload("res://tests/experimental/adaptive_tests.gd")

func _initialize() -> void:
	call_deferred("_run")


func _run() -> void:
	var options: Dictionary = {"scenario": "late_wait", "duration": "60", "repeats": "1", "profile": "false", "short_exact": "600"}
	for argument in OS.get_cmdline_user_args():
		var pair: PackedStringArray = argument.trim_prefix("--").split("=", true, 1)
		if pair.size() == 2:
			options[pair[0]] = pair[1]
	var test = preload("res://tests/experimental/autobuyer_tests.gd").new()
	for repeat_index in range(int(options["repeats"])):
		var result: Dictionary = test.measure(options["scenario"], float(options["duration"]), options["profile"] == "true", float(options["short_exact"]))
		result["repeat"] = repeat_index
		result["engine"] = Engine.get_version_info()["string"]
		print("AUTOBUYER_JSON " + JSON.stringify(result))
		if not test.failures.is_empty():
			for failure in test.failures:
				push_error(failure)
			quit(1)
			return
	quit()

performance_stage_sources.autobuyer_fixtures.gd:
extends RefCounted

const Existing = preload("res://tests/experimental/horizon_fixtures.gd")

class TickLog extends RefCounted:
	var events: Array[Dictionary] = []
	var clock: Callable
	func record_event(category: String, event: String, details: Dictionary = {}, source: String = "game") -> void:
		events.append({"category": category, "event": event, "details": details.duplicate(true),
			"source": source, "tick": roundi(float(clock.call()) / TimeManager.OFFLINE_MAX_GAME_STEP) if clock.is_valid() else 0})


static func enable(state: GameState, id: String, upgrades: bool = false) -> void:
	var manager = state.upgrade_automation_manager if upgrades else state.generator_automation_manager
	state.eternal_flame_state.unlock_technology(manager.get_automation_technology_id(id))
	manager.set_enabled(id, true)


static func make_state(scenario: String) -> GameState:
	var state: GameState
	if scenario in ["late_wait", "late_upgrade", "late_both", "late_dynamic"]:
		state = Existing.make_state("feedback")
		var furnace: Generator = state.get_generator("matter_furnace")
		furnace.unlocked = true
		furnace.set_operation_mode("ash_production")
		state.set_resource_amount(ResourceIds.MATTER, furnace.get_cost(state) * 0.5)
		if scenario != "late_upgrade":
			enable(state, furnace.definition.id)
		if scenario in ["late_upgrade", "late_both"]:
			enable(state, furnace.definition.id, true)
		if scenario == "late_dynamic":
			var modifier := Modifier.new(ModifierTypes.COST, furnace.definition.cost_resource_id, 1.0)
			modifier.dynamic = true
			modifier.dynamic_resource_id = ResourceIds.HEAT
			modifier.dynamic_formula = Modifier.DYNAMIC_RESOURCE_LOG10
			furnace.modifiers.append(modifier)
	elif scenario == "mixed":
		state = Existing.make_state("mixed")
	elif scenario in ["middle", "consumption", "oscillation"]:
		state = Existing.make_state("automation")
		if scenario != "middle":
			for id in UpgradeAutomationManager.AUTOMATABLE_GENERATOR_IDS:
				enable(state, id, true)
		if scenario == "oscillation":
			var generator: Generator = state.get_generator("atomic_friction")
			state.set_resource_amount(ResourceIds.HEAT, generator.get_cost(state) * 1.001)
	elif scenario == "all_wait":
		state = Existing.make_state("automation")
		for generator in state.generators.values():
			generator.manually_paused = true
		state.set_resource_amount(ResourceIds.HEAT, 0.0)
		state.set_resource_amount(ResourceIds.MATTER, 0.0)
	else:
		state = Existing.make_state("early")
		enable(state, "atomic_friction")
		if scenario == "competing":
			state.get_generator("molecular_agitation").unlocked = true
			enable(state, "molecular_agitation")
			state.set_resource_amount(ResourceIds.HEAT, 1000.0)
		elif scenario == "unlock":
			var generator: Generator = state.get_generator("atomic_friction")
			generator.level = 24
			state.set_resource_amount(ResourceIds.HEAT, generator.get_cost(state) * 0.99)
		elif scenario == "upgrades":
			enable(state, "atomic_friction", true)
			state.set_resource_amount(ResourceIds.HEAT, 10000.0)
		elif scenario == "technology_locked":
			state.eternal_flame_state.unlocked_technologies.erase(state.generator_automation_manager.get_automation_technology_id("atomic_friction"))
	state.gameplay_log = TickLog.new()
	return state

performance_stage_sources.autobuyer_activity.gd:
extends RefCounted

# Optional instrumentation only; never used for throughput measurements.
class GeneratorProbe extends GeneratorAutomationManager:
	var metrics: Dictionary = {"entry_evaluations": 0, "waiting_checks": 0, "attempts": 0,
		"no_affordable_seconds": 0.0, "unlock_wait_seconds": 0.0, "body_usec": 0}
	func update(delta: float, simulation: Simulation, offline_mode: bool = false) -> void:
		for id in automation_states:
			if not is_enabled(id):
				continue
			metrics["entry_evaluations"] += 1
			var generator: Generator = state.get_generator(id)
			if not is_automation_unlocked(id) or generator == null or not generator.unlocked:
				metrics["unlock_wait_seconds"] += delta
			elif not simulation.can_buy_generator(id):
				metrics["no_affordable_seconds"] += delta
			if automation_states[id]["waiting_for_resources"]:
				metrics["waiting_checks"] += 1
		var start: int = Time.get_ticks_usec()
		super(delta, simulation, offline_mode)
		metrics["body_usec"] += Time.get_ticks_usec() - start
	func _attempt_purchase(id: String, simulation: Simulation, checked: bool = false) -> void:
		metrics["attempts"] += 1
		super(id, simulation, checked)


class UpgradeProbe extends UpgradeAutomationManager:
	var metrics: Dictionary = {"entry_evaluations": 0, "attempts": 0,
		"no_affordable_seconds": 0.0, "unlock_wait_seconds": 0.0, "body_usec": 0}
	func update(delta: float, simulation: Simulation, offline_mode: bool = false) -> void:
		for id in automation_states:
			if not is_enabled(id):
				continue
			metrics["entry_evaluations"] += 1
			var generator: Generator = state.get_generator(id)
			if not is_automation_unlocked(id) or (id != GENERAL_TREE_ID and (generator == null or not generator.unlocked)):
				metrics["unlock_wait_seconds"] += delta
				continue
			var affordable: bool = false
			for upgrade in state.upgrades.values():
				if _upgrade_belongs_to_tree(upgrade.definition, id) and (upgrade.definition.exclusivity_group == "" or is_exclusive_preference_selected(upgrade.definition.id)) and simulation.can_buy_upgrade(upgrade.definition.id):
					affordable = true
					break
			if not affordable:
				metrics["no_affordable_seconds"] += delta
		var start: int = Time.get_ticks_usec()
		super(delta, simulation, offline_mode)
		metrics["body_usec"] += Time.get_ticks_usec() - start
	func _attempt_purchase(id: String, simulation: Simulation) -> bool:
		metrics["attempts"] += 1
		return super(id, simulation)


static func install(state: GameState) -> void:
	var generator := GeneratorProbe.new(state)
	generator.automation_states = state.generator_automation_manager.automation_states.duplicate(true)
	var upgrade := UpgradeProbe.new(state)
	upgrade.automation_states = state.upgrade_automation_manager.automation_states.duplicate(true)
	upgrade.exclusive_preferences = state.upgrade_automation_manager.exclusive_preferences.duplicate(true)
	state.generator_automation_manager = generator
	state.upgrade_automation_manager = upgrade

performance_stage_sources.autobuyer_tests.gd:
extends "res://tests/experimental/adaptive_tests.gd"

const EventRunner = preload("res://tests/experimental/autobuyer_offline.gd")
const Previous = preload("res://tests/experimental/horizon_runner.gd")
const EventFixtures = preload("res://tests/experimental/autobuyer_fixtures.gd")
const Boundary = preload("res://tests/experimental/autobuyer_boundary.gd")


func make_runner(scenario: String, kind: String, short_exact: float = 0.0):
	var state: GameState = EventFixtures.make_state(scenario)
	var runner = Previous.new(Simulation.new(state)) if kind == "previous" else EventRunner.new(Simulation.new(state))
	if kind == "precise":
		runner.accuracy_mode = "precise"
	runner.overrides = {"short_exact_seconds": short_exact}
	var clock_ref: WeakRef = weakref(runner)
	state.gameplay_log.clock = func() -> float: return float(clock_ref.get_ref().elapsed)
	observe(runner.simulation)
	return runner


func measure(scenario: String, seconds: float, profile: bool = false, short_exact: float = 0.0) -> Dictionary:
	var result: Dictionary = {"scenario": scenario, "duration": seconds, "profiled": profile, "runs": {}}
	var candidates: Dictionary = {}
	# Serial, separate timers; no reference caches or diagnostic CPU attribution
	# mixed into the non-profiled measurements.
	for kind in ["precise", "previous", "event"]:
		var runner = make_runner(scenario, kind, short_exact)
		if profile:
			preload("res://tests/experimental/autobuyer_activity.gd").install(runner.simulation.state)
		runner.simulation.profiling_enabled = profile
		var start: int = Time.get_ticks_usec()
		var counters: Dictionary = runner.run(seconds)
		var wall: float = float(Time.get_ticks_usec() - start) / 1e6
		check(counters.get("strict_failure", "") == "", "Trial failure: " + scenario + "/" + kind + ": " + str(counters))
		candidates[kind] = runner
		var purchases: Array = []
		for event in runner.simulation.state.gameplay_log.events:
			if event["category"] == "purchase":
				purchases.append(event)
		result["runs"][kind] = {"seconds": wall, "counters": counters, "purchases": purchases,
			"profile": runner.simulation.get_profile_report() if profile else {},
			"activity": {"generator": runner.simulation.state.generator_automation_manager.get("metrics"), "upgrade": runner.simulation.state.upgrade_automation_manager.get("metrics")} if profile else {}}
		print("AUTOBUYER_PHASE " + JSON.stringify({"kind": kind, "scenario": scenario, "seconds": wall}))
	var reference = candidates["precise"]
	for kind in ["previous", "event"]:
		var runner = candidates[kind]
		var comparison: Dictionary = validate(reference, runner, scenario + "/" + kind)
		comparison["speedup"] = float(result["runs"]["precise"]["seconds"]) / maxf(float(result["runs"][kind]["seconds"]), 1e-9)
		result["runs"][kind].merge(comparison)
	result["failure_count"] = failures.size()
	return result


func validate(reference, runner, label: String) -> Dictionary:
	var state: GameState = runner.simulation.state
	var expected: GameState = reference.simulation.state
	var discrete: bool = Metrics.discrete(state) == Metrics.discrete(expected)
	var rng: bool = state.gameplay_rng.state == expected.gameplay_rng.state
	var reward: bool = PrestigeSystem.new().calculate_eternal_flame_gain(state) == PrestigeSystem.new().calculate_eternal_flame_gain(expected)
	var maximum: Dictionary = {"normalized": 0.0, "resource_abs": 0.0, "resource_rel": 0.0, "statistics_abs": 0.0, "statistics_rel": 0.0}
	for tick in runner.samples:
		if not reference.samples.has(tick):
			continue
		var actual: Dictionary = runner.samples[tick]
		var original: Dictionary = reference.samples[tick]
		discrete = discrete and actual["discrete"] == original["discrete"]
		rng = rng and actual["rng"] == original["rng"]
		reward = reward and actual["prestige"] == original["prestige"]
		var difference: Dictionary = Metrics.compare(original["numeric"], actual["numeric"], 1e-8, 1e-4)
		for key in maximum:
			maximum[key] = maxf(float(maximum[key]), float(difference[key]))
	var final_error: Dictionary = Metrics.compare(Metrics.numeric(expected, reference.manager), Metrics.numeric(state, runner.manager), 1e-8, 1e-4)
	check(discrete, "Discrete/purchase tick or cost mismatch: " + label)
	check(rng, "RNG mismatch: " + label)
	check(reward, "Prestige mismatch: " + label)
	check(float(maximum["normalized"]) <= 1.0 and float(final_error["normalized"]) <= 1.0, "Numerical target exceeded: " + label)
	return {"discrete_parity": discrete, "rng_parity": rng, "prestige_parity": reward,
		"maximum_sampled_deviation": maximum, "final_deviation": final_error,
		"exact_state": full(state) == full(expected), "adaptive_coverage": 1.0 - float(runner.counters.get("fallback_fraction", 1.0))}


func test_waiting() -> void:
	for scenario in ["late_wait", "late_upgrade", "late_both", "technology_locked"]:
		var reference = make_runner(scenario, "precise")
		var runner = make_runner(scenario, "event")
		reference.run(120.0)
		runner.run(120.0)
		validate(reference, runner, scenario)
		check(runner.counters["accepted"] > 0, "Proven waiting scenario did not adapt: " + scenario)
		check(runner.counters["strict_failure"] == "", "Waiting trial failed: " + scenario)


func test_purchase_boundaries() -> void:
	for scenario in ["early", "competing", "unlock", "upgrades", "middle", "consumption", "oscillation", "mixed"]:
		var reference = make_runner(scenario, "precise")
		var runner = make_runner(scenario, "event")
		reference.run(60.0)
		runner.run(60.0)
		validate(reference, runner, scenario)
		check(full(reference.simulation.state) == full(runner.simulation.state), "Unsupported purchase scenario was not binary exact: " + scenario)
		check(runner.counters["accepted"] == 0, "Growing-resource affordability/consumer/cycle scenario adapted: " + scenario)
	for seconds in [4.9, 5.0, 5.1, 9.9, 10.0, 10.1, 20.05]:
		var reference = make_runner("upgrades", "precise")
		var runner = make_runner("upgrades", "event")
		reference.run(seconds)
		runner.run(seconds)
		validate(reference, runner, "cooldown boundary " + str(seconds))
		check(full(reference.simulation.state) == full(runner.simulation.state), "Cooldown boundary changed binary state.")


func test_proof_invalidation() -> void:
	var runner = make_runner("late_wait", "event")
	# Settle the real cache, never fabricate a waiting dictionary.
	runner.simulation.update(6.0, true)
	check(Boundary.inspect(runner.simulation)["status"] == "provably_waiting", "Settled real waiting cache was not proved.")
	var furnace: Generator = runner.simulation.state.get_generator("matter_furnace")
	furnace.level += 1
	check(Boundary.inspect(runner.simulation)["status"] == "generator_wait_transition", "Level change reused stale cost.")
	runner.simulation.update(0.1, true)
	check(Boundary.inspect(runner.simulation)["status"] == "provably_waiting", "Cost refresh did not restore proof.")
	runner.simulation.state.set_resource_amount(ResourceIds.MATTER, furnace.get_cost(runner.simulation.state))
	check(Boundary.inspect(runner.simulation)["status"] == "currently_affordable", "Affordable purchase was declared idle.")
	var dynamic = make_runner("late_dynamic", "event")
	dynamic.simulation.update(6.0, true)
	check(Boundary.inspect(dynamic.simulation)["status"] == "dynamic_cost", "Dynamic cost was treated as static.")


func test_zero_short() -> void:
	for seconds in [0.0, 0.01, 0.15, 30.0]:
		var reference = make_runner("late_both", "precise")
		var runner = make_runner("late_both", "event", 600.0)
		reference.run(seconds)
		runner.run(seconds)
		check(full(reference.simulation.state) == full(runner.simulation.state), "Short/zero mitigation changed state.")

performance_stage_sources.autobuyer_boundary.gd:
extends RefCounted

# An invariant resource box, not a current-rate extrapolation. Valid only inside
# the inherited continuous-only guard: no purchases, unlocks, cycles or consumers.
# A source-free resource cannot increase under the existing environmental sinks.
static func inspect(simulation: Simulation) -> Dictionary:
	var state: GameState = simulation.state
	var sources: Dictionary = {}
	for generator in state.generators.values():
		if not generator.unlocked or generator.manually_paused or (generator.level <= 0 and not generator.operating):
			continue
		for output in generator.get_active_outputs():
			if output.unlocked:
				sources[output.resource_id] = true
	var upper: Dictionary = {}
	for id in state.resources:
		if not sources.has(id):
			var amount: float = state.get_resource_amount(id)
			if is_finite(amount) and amount >= 0.0:
				upper[id] = amount
	var enabled: bool = false
	var gm: GeneratorAutomationManager = state.generator_automation_manager
	for id in gm.automation_states:
		var entry: Dictionary = gm.automation_states[id]
		if not entry["enabled"]:
			continue
		enabled = true
		var generator: Generator = state.get_generator(id)
		if not gm.is_automation_unlocked(id) or generator == null or not generator.unlocked:
			continue
		if simulation.can_buy_generator(id):
			return _failure("currently_affordable")
		if not entry["waiting_for_resources"] or gm._waiting_cost_needs_refresh(generator, entry):
			return _failure("generator_wait_transition")
		# Reject dynamic cost AND sensitivity dependencies; do not guess a lower
		# bound for arbitrary resource-dependent formulas or mode-specific effects.
		for modifier in generator.modifiers:
			if modifier.type in [ModifierTypes.COST, ModifierTypes.COST_SCALING]:
				if modifier.dynamic:
					return _failure("dynamic_cost")
				for sensitivity in generator.modifier_sensitivities:
					if sensitivity.modifier_id == modifier.id and sensitivity.dynamic:
						return _failure("dynamic_cost_sensitivity")
		var cost: float = generator.get_cost(state)
		if not is_finite(cost) or cost != float(entry["waiting_cost"]):
			return _failure("waiting_cost_mismatch")
		var resource: String = generator.definition.cost_resource_id
		if not upper.has(resource) or float(upper[resource]) >= cost:
			return _failure("unknown_resource_bound")
	var um: UpgradeAutomationManager = state.upgrade_automation_manager
	for id in um.automation_states:
		if not um.automation_states[id]["enabled"]:
			continue
		enabled = true
		if not um.is_automation_unlocked(id):
			continue
		var generator: Generator = state.get_generator(id)
		if id != UpgradeAutomationManager.GENERAL_TREE_ID and (generator == null or not generator.unlocked):
			continue
		for upgrade in state.upgrades.values():
			var definition: UpgradeDefinition = upgrade.definition
			if not um._upgrade_belongs_to_tree(definition, id) or upgrade.is_maxed():
				continue
			if definition.exclusivity_group != "" and not um.is_exclusive_preference_selected(definition.id):
				continue
			if simulation.can_buy_upgrade(definition.id):
				return _failure("currently_affordable")
			# Any unmet non-resource requirement is invariant while the parent
			# guard excludes every automatic/discrete transition and purchase.
			var blocked: bool = not state.upgrade_system.upgrade_exclusivity_available(upgrade)
			for requirement in definition.requirements:
				if not state.upgrade_system.requirement_met(requirement):
					if requirement.type != RequirementTypes.RESOURCE:
						blocked = true
					elif upper.has(requirement.target_id) and float(upper[requirement.target_id]) < requirement.value:
						blocked = true
			if blocked:
				continue
			var cost: float = simulation.get_upgrade_cost(upgrade)
			if not is_finite(cost) or not upper.has(definition.cost_resource_id) or float(upper[definition.cost_resource_id]) >= cost:
				return _failure("unknown_upgrade_bound")
	return {"status": "provably_waiting" if enabled else "disabled", "upper": upper}


static func _failure(reason: String) -> Dictionary:
	return {"status": reason, "upper": {}}

performance_stage_sources.autobuyer_offline.gd:
extends "res://tests/experimental/horizon_runner.gd"

const Boundary = preload("res://tests/experimental/autobuyer_boundary.gd")
var event_automation_enabled: bool = true
var boundary_calls: int = 0
var boundary_usec: int = 0
var boundary_reasons: Dictionary = {}
var skipped_waiting_checks: int = 0
var cooldown_replay_usec: int = 0
var cooldown_replay_ticks: int = 0
var _proof: Dictionary = {}
var _in_trial: bool = false
var _reference_elapsed: float = 0.0


func run(seconds: float) -> Dictionary:
	_reference_elapsed = 0.0
	_in_trial = false
	boundary_calls = 0
	boundary_usec = 0
	boundary_reasons.clear()
	skipped_waiting_checks = 0
	cooldown_replay_usec = 0
	cooldown_replay_ticks = 0
	var result: Dictionary = super(seconds)
	result["automation_boundary"] = {"calls": boundary_calls, "usec": boundary_usec,
		"reasons": boundary_reasons.duplicate(), "skipped_waiting_checks": skipped_waiting_checks,
		"cooldown_replay_usec": cooldown_replay_usec, "cooldown_replay_ticks": cooldown_replay_ticks}
	return result


func _automation_guard() -> String:
	if not event_automation_enabled:
		return super()
	var start: int = Time.get_ticks_usec()
	_proof = Boundary.inspect(simulation)
	boundary_usec += Time.get_ticks_usec() - start
	boundary_calls += 1
	var status: String = _proof["status"]
	boundary_reasons[status] = int(boundary_reasons.get(status, 0)) + 1
	return "" if status in ["disabled", "provably_waiting"] else "automation_" + status


func _trial_active(active: bool) -> void:
	_in_trial = active


func _advance(delta: float, end: float) -> void:
	if not _in_trial:
		# Match the authoritative grid even after macro-step clock additions.
		var reference_delta: float = minf(REFERENCE_STEP, duration - _reference_elapsed)
		_reference_elapsed = minf(duration, _reference_elapsed + reference_delta)
		super(reference_delta, end)
		return
	# The proof applies to the entire interval. Trial probes must not mutate
	# cooldowns or waiting dictionaries; the restricted checkpoint omits them.
	# Temporarily suppress original managers, then restore flags and indices.
	var saved: Array[Dictionary] = []
	for automation in [simulation.state.generator_automation_manager, simulation.state.upgrade_automation_manager]:
		var flags: Dictionary = {}
		for id in automation.automation_states:
			flags[id] = automation.automation_states[id]["enabled"]
			automation.automation_states[id]["enabled"] = false
		saved.append(flags)
		automation.invalidate_offline_index()
	super(delta, end)
	var managers: Array = [simulation.state.generator_automation_manager, simulation.state.upgrade_automation_manager]
	for index in range(managers.size()):
		for id in saved[index]:
			managers[index].automation_states[id]["enabled"] = saved[index][id]
		managers[index].invalidate_offline_index()
	for id in _proof.get("upper", {}):
		if simulation.state.get_resource_amount(id) > float(_proof["upper"][id]):
			trial_failure_reason = "automation_invariant_violation"


func _commit_interval(ticks: int, _seconds: float) -> void:
	# Generator waiting entries are constant after cache stabilization. Upgrade
	# cooldowns are not: replay the production manager on the reference grid.
	# No purchase is possible at ANY resource value inside the proven box, so
	# using the final amounts for these failed checks is equivalent. This keeps
	# exact floating subtraction/overshoot; it deliberately leaves O(ticks) work.
	var state: GameState = simulation.state
	for id in state.generator_automation_manager.automation_states:
		var entry: Dictionary = state.generator_automation_manager.automation_states[id]
		if entry["enabled"] and entry["waiting_for_resources"]:
			skipped_waiting_checks += ticks
	var enabled_upgrade: bool = false
	for entry in state.upgrade_automation_manager.automation_states.values():
		enabled_upgrade = enabled_upgrade or bool(entry["enabled"])
	var start: int = Time.get_ticks_usec()
	for _index in range(ticks):
		var delta: float = minf(REFERENCE_STEP, duration - _reference_elapsed)
		_reference_elapsed = minf(duration, _reference_elapsed + delta)
		if enabled_upgrade:
			state.upgrade_automation_manager.update(delta, simulation, true)
			cooldown_replay_ticks += 1
	cooldown_replay_usec += Time.get_ticks_usec() - start

performance_stage_sources.adaptive_offline.gd:
extends RefCounted

# ISOLATED EXPERIMENT. Nothing in production preloads or calls this class.
# Step doubling estimates the error of the existing ordered update map. It is
# not a proof of accuracy relative to repeated 0.1 s updates: audit that separately.
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")
const Checkpoint = preload("res://tests/experimental/continuous_checkpoint.gd")
const REFERENCE_STEP: float = TimeManager.OFFLINE_MAX_GAME_STEP

var maximum_step: float = 60.0
var minimum_step: float = REFERENCE_STEP
var absolute_tolerance: float = 1e-8
var relative_tolerance: float = 1e-4
var event_safety_margin: float = 0.1
var fallback_window_ticks: int = 10
var audit_interval: float = 60.0
var distribute_error_budget: bool = true
var force_exact: bool = false
var allow_environmental_feedback: bool = true
# Diagnostics are optional: per-attempt traces are excluded from throughput runs.
var numerical_retry_max_ticks: int = 0
var trial_failure_reason: String = ""
var trace_attempts: bool = false
var attempts: Array[Dictionary] = []
var profile_checkpoints: bool = false

var counters: Dictionary = {}
var samples: Dictionary = {}
var simulation: Simulation
var manager: TimeManager
var elapsed: float = 0.0
var duration: float = 0.0

func _init(game_simulation: Simulation) -> void:
	simulation = game_simulation
	manager = TimeManager.new(simulation)


# There are no generator-specific shortcuts. Consumers, discrete production,
# stateful/dormancy modifiers and discrete controllers deliberately fall back.
func guard() -> String:
	var state: GameState = simulation.state
	if force_exact:
		return "forced_exact"
	if not allow_environmental_feedback and (state.get_heat_leak_per_second() > 0.0 or state.get_matter_decay_per_second() > 0.0):
		return "environmental_feedback"
	if simulation.profiling_enabled or simulation.diagnostics_enabled:
		return "instrumented_simulation"
	if state.prestige_planning:
		return "prestige_planning"
	var automation_reason: String = _automation_guard()
	if automation_reason != "":
		return automation_reason
	var changing: Dictionary = {}
	for g in state.generators.values():
		if g.cycle_active or g.auto_run_cycles:
			return "cycle_or_auto_run"
		if g.definition.cycle_based:
			continue
		if not g.unlocked:
			continue
		# Throttle flags can change even for paused/level-zero consumers.
		if not g.get_active_inputs().is_empty():
			return "resource_consumers"
		if g.manually_paused and g.operating:
			return "pause_transition"
		if g.manually_paused or g.level <= 0:
			continue
		if not g.operating or g.is_throttled:
			return "operating_transition"
		for modifier in g.modifiers:
			if modifier.dynamic and modifier.dynamic_formula == Modifier.DYNAMIC_LAVA_MITE_DORMANCY:
				return "time_dependent_modifier"
		for output in g.get_active_outputs():
			if not output.unlocked:
				continue
			if output.discrete:
				return "discrete_production"
			changing[output.resource_id] = true
			if not state.is_resource_discovered(output.resource_id):
				return "discovery_boundary"
	if state.get_heat_leak_per_second() > 0.0:
		changing[ResourceIds.HEAT] = true
	if state.get_matter_decay_per_second() > 0.0:
		changing[ResourceIds.MATTER] = true
		changing[ResourceIds.HEAT] = true
	# Every pending automatic upgrade must have an immutable unmet requirement.
	# Otherwise evaluate exact ticks, including the original ordered application.
	for u in state.upgrades.values():
		if not u.definition.automatic or u.is_maxed():
			continue
		var blocked: bool = false
		for requirement in u.definition.requirements:
			if not state.upgrade_system.requirement_met(requirement):
				if requirement.type != RequirementTypes.RESOURCE or not changing.has(requirement.target_id):
					blocked = true
		if not blocked:
			return "automatic_resource_boundary"
	return ""


func _automation_guard() -> String:
	for automation in [simulation.state.generator_automation_manager, simulation.state.upgrade_automation_manager]:
		for entry in automation.automation_states.values():
			if entry["enabled"]:
				return "enabled_automation"
	return ""


func _commit_interval(_ticks: int, _seconds: float) -> void:
	pass


func _trial_active(_active: bool) -> void:
	pass


# This standalone experiment owns a fresh, scale-one TimeManager context.
# Trials have no clock callbacks; commit the interval clocks with accepted time.
func _sync_clocks() -> void:
	manager.game_time = elapsed
	manager.offline_time = elapsed
	manager.prestige_time = elapsed
	manager.current_offline_duration = elapsed


func _signature() -> String:
	var started: int = Time.get_ticks_usec()
	var result: String = Metrics.discrete(simulation.state, false)
	counters["event_detection_usec"] += Time.get_ticks_usec() - started
	return result


func _advance(delta: float, end: float) -> void:
	simulation.state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(end))
	var started: int = Time.get_ticks_usec()
	simulation.update(delta, true)
	counters["numerical_usec"] += Time.get_ticks_usec() - started
	counters["evaluations"] += 1


func _sample(tick: int) -> void:
	if samples.has(tick):
		return
	var started: int = Time.get_ticks_usec()
	samples[tick] = {"numeric": Metrics.numeric(simulation.state, manager), "discrete": Metrics.discrete(simulation.state),
		"rng": str(simulation.state.gameplay_rng.state)}
	counters["audit_capture_usec"] += Time.get_ticks_usec() - started


func _capture_checkpoint() -> Dictionary:
	var start: int = Time.get_ticks_usec() if profile_checkpoints else 0
	var value: Dictionary = Checkpoint.capture(simulation)
	if profile_checkpoints:
		counters["all_capture_usec"] += Time.get_ticks_usec() - start
		counters["capture_calls"] += 1
	return value


func _restore_checkpoint(value: Dictionary) -> void:
	var start: int = Time.get_ticks_usec() if profile_checkpoints else 0
	Checkpoint.restore(simulation, value)
	if profile_checkpoints:
		counters["all_restore_usec"] += Time.get_ticks_usec() - start
		counters["restore_calls"] += 1


func _near_boundary_requires_exact(_resource: String, _before: float, _coarse: float, _fine: float) -> bool:
	return true


func _completed_interval(_ticks: int, _adaptive: bool) -> void:
	pass


func run(seconds: float) -> Dictionary:
	elapsed = 0.0
	duration = maxf(seconds, 0.0)
	samples.clear()
	attempts.clear()
	counters = {"evaluations": 0, "accepted": 0, "rejected": 0, "fallback_ticks": 0,
		"proven_margin_bypasses": 0, "fallback_reasons": {}, "rejection_reasons": {}, "rejection_fields": {}, "rejected_usec": 0, "event_detection_usec": 0, "trial_usec": 0, "fallback_usec": 0,
		"all_capture_usec": 0, "all_restore_usec": 0, "capture_calls": 0, "restore_calls": 0, "checkpoint_usec": 0, "numerical_usec": 0, "audit_capture_usec": 0, "initial_checkpoint_bytes": 0, "strict_failure": ""}
	var finite_configuration: bool = true
	for value in [seconds, maximum_step, minimum_step, absolute_tolerance, relative_tolerance, event_safety_margin, audit_interval]:
		finite_configuration = finite_configuration and is_finite(value)
	if not finite_configuration or not is_finite(maximum_step) or maximum_step < REFERENCE_STEP or minimum_step < REFERENCE_STEP or absolute_tolerance <= 0.0 or relative_tolerance < 0.0 or event_safety_margin < 0.0:
		counters["strict_failure"] = "Invalid experimental configuration; no simulation was performed."
		return counters
	if manager.time_scale != 1.0 or manager.stabilization_countdown_active or manager.dormancy_recovery_remaining != 0.0 or manager.game_time != 0.0:
		counters["strict_failure"] = "Unsupported TimeManager context; use a fresh scale-one experimental interval."
		return counters
	if duration <= 0.0:
		return counters
	var total_ticks: int = ceili(duration / REFERENCE_STEP)
	var audit_ticks: int = maxi(1, floori(audit_interval / REFERENCE_STEP))
	var max_ticks: int = maxi(1, floori(maximum_step / REFERENCE_STEP))
	var min_ticks: int = maxi(2, ceili(minimum_step / REFERENCE_STEP))
	var proposal: int = min_ticks
	var tick: int = 0
	var retry_ticks: int = 0
	simulation.state.simulation_statistics = manager.simulation_statistics
	simulation.prepare_offline()
	while tick < total_ticks:
		var completed_ticks: int = 0
		var completed_adaptive: bool = false
		var checkpoint_tick: int = mini(total_ticks, (floori(float(tick) / float(audit_ticks)) + 1) * audit_ticks)
		var start: int = Time.get_ticks_usec()
		var reason: String = guard()
		counters["event_detection_usec"] += Time.get_ticks_usec() - start
		var n: int = mini(mini(proposal, max_ticks), checkpoint_tick - tick)
		if reason != "" or n < min_ticks:
			start = Time.get_ticks_usec()
			var count: int = mini(maxi(maxi(1, fallback_window_ticks), retry_ticks), checkpoint_tick - tick)
			if reason == "" and retry_ticks > 0:
				reason = "numerical_retry_cooldown"
			for _index in range(count):
				var delta: float = minf(REFERENCE_STEP, duration - elapsed)
				if delta > 0.0:
					elapsed = minf(duration, elapsed + delta)
					_sync_clocks()
					_advance(delta, elapsed)
				tick += 1
				counters["fallback_ticks"] += 1
			counters["fallback_reasons"][reason if reason != "" else "minimum_step"] = int(counters["fallback_reasons"].get(reason if reason != "" else "minimum_step", 0)) + count
			counters["fallback_usec"] += Time.get_ticks_usec() - start
			proposal = min_ticks
			completed_ticks = count
		else:
			_trial_active(true)
			start = Time.get_ticks_usec()
			var attempt_start: int = start
			trial_failure_reason = ""
			var saved: Dictionary = _capture_checkpoint()
			counters["checkpoint_usec"] += Time.get_ticks_usec() - start
			if counters["initial_checkpoint_bytes"] == 0:
				counters["initial_checkpoint_bytes"] = var_to_bytes(saved).size()
			var signature: String = _signature()
			var rng: int = simulation.state.gameplay_rng.state
			var h: float = minf(float(n) * REFERENCE_STEP, duration - elapsed)
			start = Time.get_ticks_usec()
			_advance(h, elapsed + h)
			var coarse: Dictionary = Metrics.numeric(simulation.state)
			if _signature() != signature or simulation.state.gameplay_rng.state != rng:
				_trial_active(false)
				counters["strict_failure"] = "Unexpected coarse-trial discrete event; discard this experimental state."
				return counters
			_restore_checkpoint(saved)
			var first: float = float(n >> 1) * REFERENCE_STEP
			_advance(first, elapsed + first)
			_advance(h - first, elapsed + h)
			var fine: Dictionary = Metrics.numeric(simulation.state)
			counters["trial_usec"] += Time.get_ticks_usec() - start
			if _signature() != signature or simulation.state.gameplay_rng.state != rng:
				_trial_active(false)
				counters["strict_failure"] = "Unexpected fine-trial discrete event; discard this experimental state."
				return counters
			_trial_active(false)
			var error: float = 0.0
			var worst_field: String = ""
			var rejection_reason: String = "numerical_error"
			for key in coarse:
				if not fine.has(key):
					fine[key] = 0.0
			for key in fine:
				var a: float = float(coarse.get(key, 0.0))
				var b: float = float(fine[key])
				var budget: float = absolute_tolerance + relative_tolerance * maxf(absf(a), absf(b))
				if distribute_error_budget and not str(key).ends_with("highest_amount"):
					budget *= h / duration
				var value: float = absf(a - b) / maxf(budget, 1e-30) if is_finite(a) and is_finite(b) else INF
				if value > error:
					error = value
					worst_field = str(key)
			# Reject environmental threshold crossings, leaving the crossing on
			# the authoritative grid. Margin is in resource units, not seconds.
			for pair in [[ResourceIds.HEAT, simulation.state.realm_effects.heat_leak_threshold], [ResourceIds.MATTER, simulation.state.realm_effects.matter_decay_threshold]]:
				var before: float = saved["amounts"][pair[0]] - float(pair[1])
				var after: float = fine["resource/" + pair[0]] - float(pair[1])
				if before * after < 0.0 or (absf(after) < event_safety_margin and before != after and _near_boundary_requires_exact(pair[0], float(saved["amounts"][pair[0]]), float(coarse.get("resource/" + pair[0], fine["resource/" + pair[0]])), float(fine["resource/" + pair[0]]))):
					error = INF
					rejection_reason = "environmental_threshold"
			if trial_failure_reason != "":
				error = INF
				rejection_reason = trial_failure_reason
			if trace_attempts:
				attempts.append({"tick": tick, "ticks": n, "error": error, "field": worst_field, "reason": rejection_reason if error > 1.0 else "accepted", "usec": Time.get_ticks_usec() - attempt_start})
			if error <= 1.0:
				elapsed = minf(duration, elapsed + h)
				_sync_clocks()
				tick += n
				counters["accepted"] += 1
				retry_ticks = 0
				_commit_interval(n, h)
				_sample(tick) # Audit every accepted endpoint, plus fixed checkpoints.
				proposal = mini(max_ticks, n * 2) if error < 0.25 else n
				completed_ticks = n
				completed_adaptive = true
			else:
				_restore_checkpoint(saved)
				counters["rejected"] += 1
				counters["rejected_usec"] += Time.get_ticks_usec() - attempt_start
				counters["rejection_reasons"][rejection_reason] = int(counters["rejection_reasons"].get(rejection_reason, 0)) + 1
				counters["rejection_fields"][worst_field] = int(counters["rejection_fields"].get(worst_field, 0)) + 1
				proposal = n >> 1
				if proposal < min_ticks and numerical_retry_max_ticks > 0:
					retry_ticks = mini(numerical_retry_max_ticks, maxi(fallback_window_ticks, retry_ticks * 2))
		if tick == checkpoint_tick:
			_sample(tick)
		if completed_ticks > 0:
			_completed_interval(completed_ticks, completed_adaptive)
	counters["fallback_fraction"] = float(counters["fallback_ticks"]) / float(total_ticks)
	return counters.duplicate(true)

